<i class="Summary5 fa fa-book"></i>
<a class="Summary6" href="#multithreading_gestion-du-fichier-cmake">Gestion du fichier CMake</a>
</div>
<div class="GSummary21 Summary4">
<i class="Summary5 fa fa-book"></i>
<a class="Summary6" href="#multithreading_execution-du-projet">Exécution du projet</a>
</div>
</div><br><h2 class="GTitle1 Title1">
<a class="Title2" id="multithreading_gestion-du-programme-principal" href="#multithreading">Gestion du programme principal</a>
</h2><br><span class="GText2" style="
color: #00ff00;
">// main.cpp (Editer le programme principal)</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">...
#include &lt;iostream&gt;
#include &lt;thread&gt;
#include &lt;chrono&gt;

using namespace std::chrono_literals;

static void onThread(const std::string &amp;_name);

int main(int _argc, char **_argv)
{
    std::thread oThreadA(onThread, "[ThreadA]");
    std::thread oThreadB(onThread, "[ThreadB]");
    oThreadA.join();
    oThreadB.join();
    return 0;
}

static void onThread(const std::string &amp;_name)
{
    std::cout &lt;&lt; _name &lt;&lt; " : " &lt;&lt; "Demarrage du traitement." &lt;&lt; std::endl;
    std::this_thread::sleep_for(1s);
    std::cout &lt;&lt; _name &lt;&lt; " : " &lt;&lt; "Fin du traitement." &lt;&lt; std::endl;
}
